hcl:
resource "google_pubsub_topic" "crawler_tasks" {
  name                       = "crawler-tasks"
  message_retention_duration = "86400s"
}

resource "google_pubsub_subscription" "crawl_sub" {
  name                 = "crawl-sub"
  topic                = google_pubsub_topic.crawler_tasks.id
  ack_deadline_seconds = 60
  push_config {
    push_endpoint = "${google_cloud_run_v2_service.crawler_worker.uri}/push"
    oidc_token { service_account_email = google_service_account.push.email }
  }
  retry_policy { minimum_backoff = "10s" }
  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.crawler_tasks_dlq.id
    max_delivery_attempts = 10
  }
}

resource "google_pubsub_subscription" "audit_sub" {
  name                       = "audit-sub"
  topic                      = google_pubsub_topic.crawler_tasks.id
  ack_deadline_seconds       = 30
  message_retention_duration = "604800s"
}

resource "google_pubsub_schema" "qsearch_event_v1" {
  name       = "qsearch-crawl-event-v1"
  type       = "AVRO"
  definition = file("${path.module}/schemas/qsearch-crawl-event-v1.avsc")
}

resource "google_pubsub_topic" "qsearch_fetched" {
  name = "qsearch-crawl-fetched"
  schema_settings {
    schema   = google_pubsub_schema.qsearch_event_v1.id
    encoding = "JSON"
  }
}

resource "google_pubsub_subscription" "qsearch_parser_sub" {
  name                       = "qsearch-parser-sub"
  topic                      = google_pubsub_topic.qsearch_fetched.id
  ack_deadline_seconds       = 60
  retain_acked_messages      = true
  message_retention_duration = "604800s"

  push_config {
    push_endpoint = "${google_cloud_run_v2_service.parser.uri}/push"
    oidc_token {
      service_account_email = google_service_account.push.email
    }
  }
}

resource "google_pubsub_subscription" "qsearch_to_bq" {
  name  = "qsearch-fetched-to-bq"
  topic = google_pubsub_topic.qsearch_fetched.id
  bigquery_config {
    table            = "${var.project_id}.${google_bigquery_dataset.sentiment.dataset_id}.${google_bigquery_table.ingest_events.table_id}"
    use_topic_schema = true
    write_metadata   = true
  }
}

resource "google_cloud_run_v2_service_iam_member" "worker_invoker" {
  name     = google_cloud_run_v2_service.crawler_worker.name
  location = "asia-east1"
  role     = "roles/run.invoker"
  member   = "serviceAccount:${google_service_account.push.email}"
}
resource "google_service_account_iam_member" "pubsub_token_creator" {
  service_account_id = google_service_account.push.name
  role               = "roles/iam.serviceAccountTokenCreator"
  member             = "serviceAccount:service-${var.project_number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

resource "google_cloud_scheduler_job" "crawl_tick" {
  name      = "crawl-tick"
  region    = "asia-east1"
  schedule  = "*/15 * * * *"
  time_zone = "Asia/Taipei"
  http_target {
    http_method = "POST"
    uri         = "${google_cloud_run_v2_service.scheduler.uri}/tick"
    oidc_token {
      service_account_email = google_service_account.scheduler.email
      audience              = google_cloud_run_v2_service.scheduler.uri
    }
  }
}

resource "google_cloud_tasks_queue" "crawl" {
  for_each = toset(["crawl-fb", "crawl-yt", "crawl-news"])
  name     = each.key
  location = "asia-east1"
  rate_limits {
    max_dispatches_per_second = 5
    max_concurrent_dispatches = 10
  }
  retry_config {
    max_attempts = 5
    min_backoff  = "10s"
    max_backoff  = "300s"
  }
}

resource "google_cloud_run_v2_service" "scheduler" {
  name                = "scheduler"
  location            = "asia-east1"
  deletion_protection = false
  template {
    service_account = google_service_account.scheduler_app.email
    scaling { max_instance_count = 1 }
    containers {
      image = "asia-east1-docker.pkg.dev/${var.project_id}/crawler/scheduler:latest"
    }
  }
}

resource "google_cloud_run_v2_service" "crawler_api" {
  name                = "crawler-api"
  location            = "asia-east1"
  ingress             = "INGRESS_TRAFFIC_ALL"
  deletion_protection = false
  template {
    service_account = google_service_account.api.email
    containers {
      image = "asia-east1-docker.pkg.dev/${var.project_id}/crawler/api:latest"
    }
  }
}

resource "google_cloud_run_v2_service" "crawler_worker" {
  name     = "crawler-worker"
  location = "asia-east1"
  template {
    service_account = google_service_account.push.email
    scaling { max_instance_count = 50 }
    vpc_access {
      egress = "ALL_TRAFFIC"
      network_interfaces { subnetwork = google_compute_subnetwork.crawler.id }
    }
    containers { image = "asia-east1-docker.pkg.dev/${var.project_id}/crawler/worker:latest" }
  }
}

resource "google_cloud_run_v2_service" "parser" {
  name                = "parser"
  location            = "asia-east1"
  deletion_protection = false
  template {
    service_account = google_service_account.parser.email
    scaling { max_instance_count = 20 }
    containers { image = "asia-east1-docker.pkg.dev/${var.project_id}/crawler/parser:latest" }
  }
}

resource "google_cloud_run_v2_job" "qsearch_backfill" {
  name                = "qsearch-backfill"
  location            = "asia-east1"
  deletion_protection = false
  template {
    template {
      timeout     = "3600s"
      max_retries = 2
      containers { image = "asia-east1-docker.pkg.dev/${var.project_id}/crawler/backfill:latest" }
    }
  }
}

resource "google_storage_bucket" "raw_scraped" {
  name                        = "raw-scraped-data-bucket-823e12"
  location                    = "ASIA-EAST1"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"
  lifecycle_rule {
    condition { age = 30 }
    action { type = "Delete" }
  }
}

resource "google_bigquery_dataset" "sentiment" {
  dataset_id                 = "sentiment_analytics"
  location                   = "asia-east1"
  description                = "Crawler sentiment analytics"
  delete_contents_on_destroy = false
}

resource "google_bigquery_table" "ingest_events" {
  dataset_id               = google_bigquery_dataset.sentiment.dataset_id
  table_id                 = "ingest_events"
  deletion_protection      = false
  require_partition_filter = true
  time_partitioning {
    type          = "DAY"
    expiration_ms = 7776000000
  }
}

resource "google_sql_database_instance" "crawler_db" {
  name                = "crawler-db"
  database_version    = "POSTGRES_15"
  deletion_protection = false
  settings {
    tier    = "db-custom-2-7680"
    edition = "ENTERPRISE"
    ip_configuration { private_network = google_compute_network.crawler.id }
  }
}
resource "google_sql_database" "crawler" {
  name     = "crawler"
  instance = google_sql_database_instance.crawler_db.name
}

resource "google_container_node_pool" "browser_pool" {
  name     = "browser-pool"
  cluster  = google_container_cluster.crawler_standard.name
  location = "asia-east1"
  autoscaling {
    min_node_count = 0
    max_node_count = 10
  }
  node_config {
    machine_type = "e2-standard-4"
  }
}

resource "kubernetes_horizontal_pod_autoscaler_v2" "browser" {
  metadata {
    name      = "browser-hpa"
    namespace = "crawler"
  }
  spec {
    min_replicas = 1
    max_replicas = 20
    scale_target_ref {
      kind = "Deployment"
      name = "browser"
    }
    metric {
      type = "Resource"
      resource {
        name = "cpu"
        target {
          type                = "Utilization"
          average_utilization = 70
        }
      }
    }
  }
}

resource "google_compute_instance_template" "crawler_legacy" {
  machine_type = "e2-medium"
  disk { source_image = "debian-cloud/debian-12" }
  network_interface {
    subnetwork = google_compute_subnetwork.crawler.id
  }
  service_account {
    email  = google_service_account.legacy.email
    scopes = ["cloud-platform"]
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "google_compute_region_instance_group_manager" "crawler_legacy" {
  name               = "crawler-legacy-mig"
  base_instance_name = "crawler-legacy"
  region             = "asia-east1"
  version {
    instance_template = google_compute_instance_template.crawler_legacy.self_link
  }
  target_size = 2
  auto_healing_policies {
    health_check      = google_compute_health_check.legacy.id
    initial_delay_sec = 300
  }
}

resource "google_compute_address" "egress" {
  name   = "crawler-egress-ip"
  region = "asia-east1"
}
resource "google_compute_router_nat" "crawler" {
  name                               = "crawler-nat"
  router                             = google_compute_router.crawler.name
  region                             = "asia-east1"
  nat_ip_allocate_option             = "MANUAL_ONLY"
  nat_ips                            = [google_compute_address.egress.self_link]
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"
}

resource "google_compute_router" "crawler" {
  name    = "crawler-router"
  network = google_compute_network.crawler.id
  region  = "asia-east1"
  bgp {
    asn = 64514
  }
}

resource "google_cloudbuild_trigger" "crawler_api" {
  name     = "crawler-api-main"
  location = "asia-east1"
  github {
    owner = "your-github-org"
    name  = "crawler"
    push {
      branch = "^main$"
    }
  }
  filename = "cloudbuild.yaml"
}
